import {demoFetch} from './demo-api.mjs';
import {get,put} from './offline.mjs';
import {mountMap,destroyMap} from './map.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stageNames=['Выявлен','Описан','Участники выявлены','Контакт с ЛПР','Потребность выявлена','КП направлено','Обратная связь','Клиент на объекте','Партнёрство'];
const sourceNames={office:'Из офиса',self:'Самостоятельно',client:'Через клиента'},scaleNames={small:'Малый',medium:'Средний',large:'Крупный'},partNames={customer:'Заказчик',general:'Генподрядчик',contractor:'Подрядчик',subcontractor:'Субподрядчик'},statusNames={unknown:'Не выяснено',need:'Есть потребность',quoted:'КП отправлено',feedback:'Обратная связь',ours:'У нас',competitor:'У конкурента','not-needed':'Не нужно',later:'Позже'},actionNames={visit:'Визит',meeting:'Встреча с ЛПР',call:'Звонок / переписка',quote:'КП отправлено',feedback:'Обратная связь',handoff:'Передача',clarification:'Уточнение'};
let state,session,view='dashboard',selected=null,detailTab='overview',filter={},queue=[],offline=false,picking=false,reviewIndex=0;
const today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Moscow'}),fmt=v=>v?new Date(v).toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short'}):'Не задано';
const dateTime=v=>v?new Date(v).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const uname=id=>state.users.find(u=>u.id===id)?.name||id||'Не назначен';
const pname=id=>state.settings.products.find(p=>p.id===id)?.name||id;
const construction=id=>state.settings.constructionStages.find(x=>x.id===id)?.name||id;
const ownParts=o=>state.participations.filter(p=>p.objectId===o.id),ownOpps=o=>state.opportunities.filter(x=>ownParts(o).some(p=>p.id===x.participationId));
const isLeader=()=>['leader','admin'].includes(state.user.role);
const editable=o=>isLeader()||state.user.role==='field'&&o.ownerId===state.user.id||state.user.role==='office'&&(o.createdBy===state.user.id&&!o.handoffAt||o.scale==='small'&&o.type==='Частный'&&o.officeOwnerId===state.user.id);
const canCreate=()=>['leader','admin','field','office','key'].includes(state.user.role);
const nextStep=o=>state.steps.filter(x=>x.objectId===o.id&&x.status==='planned').sort((a,b)=>a.dueAt.localeCompare(b.dueAt))[0];
const icon=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">${({dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',map:'<path d="m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3zM9 3v15M15 6v15"/>',objects:'<path d="M4 21V5h10v16M14 10h6v11M2 21h20M7 9h4M7 13h4M7 17h4"/>',clients:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',day:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4M16 3v4M4 11h16m-12 5 3 2 5-4"/>',team:'<path d="M4 21v-7h4v7m3 0V8h4v13m3 0V3h4v18"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>'})[name]||''}</svg>`;
const badge=(text,color='gray')=>`<span class="badge ${color}">${esc(text)}</span>`;
const button=(label,action,attrs='',cls='')=>`<button type="button" class="${cls}" data-act="${action}" ${attrs}>${label}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
async function api(url,options={}){const r=await demoFetch(new URL(url.replace(/^\//,''),document.baseURI),{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok)throw Object.assign(new Error(data.error),{status:r.status});return data;}
async function refresh(){try{state=await api('/api/state');offline=false;await put('state:'+state.user.id,state);}catch(e){if(e.status)throw e;offline=true;state=await get('state:'+session.user.id);if(!state)throw new Error('Первый вход требует подключения к серверу');}queue=await get('queue:'+state.user.id)||[];render();}
async function start(){try{session=await api('/api/session');await put('session',session);}catch{session=await get('session');offline=true;}if(!session?.user){login();return;}view=state?view:session.user.role==='field'?'day':'dashboard';await refresh();if(!offline)await sync();}
function login(){destroyMap();$('#app').innerHTML=`<main class="login"><div class="login-card"><div class="brand">DAYA<span>ПОЛЕВЫЕ ПРОДАЖИ</span></div><h1>Вся территория.<br>Следующий шаг.</h1><p class="muted">Рабочее пространство команды: от первого визита до партнёрства на объекте.</p><div class="notice section-space">Демонстрационная версия. Объекты, компании и профили вымышлены. Выбор профиля показывает сценарии роли и не является рабочей авторизацией DAYA.</div>${(session?.users||[]).map(u=>button(esc(u.name),'login',`data-id="${u.id}"`)).join('')}</div></main>`;}
async function loginAs(id){await api('/api/session',{method:'POST',body:JSON.stringify({userId:id})});state=null;selected=null;filter={};await start();}
async function send(type,data){const cmd={id:crypto.randomUUID(),version:state.version,type,data,userId:state.user.id};if(offline||queue.length){queue.push(cmd);await put('queue:'+state.user.id,queue);toast('Сохранено на устройстве. Ожидает отправки на сервер.');render();return {queued:true};}try{const result=await api('/api/commands',{method:'POST',body:JSON.stringify(cmd)});await refresh();toast('Изменение сохранено');return result;}catch(e){if(e.status)throw e;offline=true;queue.push(cmd);await put('queue:'+state.user.id,queue);render();toast('Связи нет. Запись сохранена на устройстве.');return {queued:true};}}
async function sync(rebase=false){if(!queue.length)return;if(rebase){await refresh();queue[0].version=state.version;delete queue[0].error;}let changed=false;while(queue.length){const cmd=queue[0];if(cmd.error&&!rebase)break;try{const r=await api('/api/commands',{method:'POST',body:JSON.stringify(cmd)});queue.shift();if(queue.length)queue[0].version=r.version;changed=true;rebase=false;}catch(e){if(e.status){cmd.error=e.message;}else offline=true;break;}await put('queue:'+state.user.id,queue);}await put('queue:'+state.user.id,queue);if(changed)await refresh();else render();}
function filtered(){return state.objects.filter(o=>(!filter.search||(o.name+' '+o.address).toLowerCase().includes(filter.search.toLowerCase()))&&(!filter.owner||o.ownerId===filter.owner)&&(!filter.territory||o.territoryId===filter.territory)&&(!filter.stage||o.stage===Number(filter.stage))&&(!filter.construction||o.constructionStage===filter.construction)&&(!filter.source||o.source===filter.source)&&(!filter.product||ownOpps(o).some(x=>x.product===filter.product))&&(!filter.client||ownParts(o).some(x=>x.clientId===filter.client))&&(!filter.focus||o.focus)&&(!filter.signals||state.signals.some(x=>x.objectId===o.id))&&(!filter.today||state.steps.some(x=>x.objectId===o.id&&x.status==='planned'&&x.dueAt.slice(0,10)===today()))&&(!filter.new||new Date(o.createdAt)>=new Date(Date.now()-Number(filter.new)*86400000)));}
function options(items,selected='',placeholder=null){return (placeholder!==null?`<option value="">${esc(placeholder)}</option>`:'')+items.map(x=>`<option value="${esc(x.id??x)}" ${String(x.id??x)===String(selected)?'selected':''}>${esc(x.name??x)}</option>`).join('');}
function filters(full=false){return `<div class="toolbar"><input class="search" data-filter="search" aria-label="Поиск объекта" placeholder="Поиск объекта или адреса" value="${esc(filter.search||'')}"><select data-filter="owner" aria-label="Менеджер">${options(state.users.filter(u=>u.role==='field'),filter.owner,'Все менеджеры')}</select><select data-filter="construction" aria-label="Стадия стройки">${options(state.settings.constructionStages,filter.construction,'Все стадии стройки')}</select><select data-filter="stage" aria-label="Этап воронки">${options(stageNames.map((name,i)=>({id:i+1,name})),filter.stage,'Все этапы')}</select>${full?`<select data-filter="territory" aria-label="Территория">${options(state.territories,filter.territory,'Все территории')}</select><select data-filter="source" aria-label="Источник">${options(Object.entries(sourceNames).map(([id,name])=>({id,name})),filter.source,'Все источники')}</select><select data-filter="product" aria-label="Продукт">${options(state.settings.products,filter.product,'Все продукты')}</select><select data-filter="client" aria-label="Клиент">${options(state.clients,filter.client,'Все клиенты')}</select><select data-filter="new" aria-label="Новые за период">${options([{id:7,name:'Новые за неделю'},{id:30,name:'Новые за месяц'}],filter.new,'Все даты создания')}</select>`:''}<label class="check"><input type="checkbox" data-filter="focus" ${filter.focus?'checked':''}> Фокусные</label><label class="check"><input type="checkbox" data-filter="signals" ${filter.signals?'checked':''}> С сигналами</label>${full?`<label class="check"><input type="checkbox" data-filter="today" ${filter.today?'checked':''}> Задачи на сегодня</label>`:''}${button('Сбросить','resetFilters','','ghost')}</div>`;}
function render(){if(!state)return;destroyMap();const nav=[['dashboard','Обзор'],['map','Карта'],['objects','Объекты'],['clients','Клиенты'],['day','Мой день'],['team','Команда'],['settings','Настройки']];const titles=Object.fromEntries(nav);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">DAYA<span>ОПЕРАЦИОННАЯ СИСТЕМА</span></div><div class="nav-label">ПОЛЕВЫЕ ПРОДАЖИ</div><nav class="nav">${nav.map(([id,name])=>`<button data-view="${id}" class="${view===id?'active':''}">${icon(id)}<span>${name}</span></button>`).join('')}</nav><div class="sidebar-bottom"><p class="muted">Один объект.<br>Больше возможностей.</p><p class="section-space muted">Версия 0.1 · для передачи<br>разработчику DAYA</p></div></aside><main class="main"><header class="topbar"><div class="crumb">DAYA OS <b>/ Полевые продажи</b></div><div class="flex"><span class="small muted"><i class="status-dot" style="${offline?'background:#c68d33':''}"></i> ${offline?'Нет связи':'Сохранение в этом браузере'}</span><select class="user-select" id="user-select" aria-label="Демонстрационный профиль">${options(state.users,state.user.id)}</select></div></header><div class="content"><div class="page-head"><div><div class="eyebrow">${view==='dashboard'?'ПУЛЬС ТЕРРИТОРИИ':'РАБОЧЕЕ ПРОСТРАНСТВО'}</div><h1>${view==='dashboard'?'Управление полевыми продажами':titles[view]}</h1><p>${view==='dashboard'?'Сначала то, что требует вашего решения.':view==='map'?'Объекты, территории и возможности на одной карте.':view==='day'?'Куда поехать, что сделать и о чём договориться.':'От объекта и клиента — к следующему действию.'}</p></div><div class="flex">${button('↻','refresh','aria-label="Обновить"')}${view==='dashboard'||view==='team'?button('Разбор недели','review'):''}${canCreate()?button('+ Объект','newObject','','primary'):''}</div></div><div class="demo"><span>ДЕМОНСТРАЦИЯ · GitHub Pages · Данные вымышлены. Изменения видны только в этом браузере.</span><span>${fmt(state.serverNow)} · ${state.settings.normsApproved?'Нормативы утверждены':'Нормативы — черновик'}</span></div>${queue.length?`<div class="outbox"><b>${queue.length} операций на устройстве</b><p>${esc(queue[0].error||'Ожидают связи. Сервер ещё не подтвердил сохранение.')}</p>${button(queue[0].error?'Проверить и повторить':'Отправить сейчас','sync')}</div>`:''}${({dashboard:dashboard,map:mapView,objects:objectsView,clients:clientsView,day:dayView,team:teamView,settings:settingsView})[view]()}</div></main></div>`;
 const map=$('#map');if(map)mountMap(map,state,filtered(),openObject,coords=>{if(picking){picking=false;newObject(coords);}});
 if(selected)renderDrawer();}
function kpi(label,value,hint){return `<div class="kpi"><div class="label">${label}</div><div class="value">${value}</div><div class="hint">${hint}</div></div>`;}
function dashboard(){const objs=filtered().filter(o=>!o.restricted),active=objs.filter(o=>o.state==='active'),with2=objs.filter(o=>(o.ourProducts?.length||0)>=2).length;return `${filters()}<div class="kpis">${kpi('Требуют внимания',state.signals.length,'Сигналы, доступные вашей роли')}${kpi('Объекты в работе',active.length,`${objs.filter(o=>o.focus).length} фокусных · ${state.territories.length} территории`)}${kpi('Два и более продукта',with2,`${objs.length?Math.round(with2/objs.length*100):0}% известных объектов`)}${kpi('Новые за 7 дней',objs.filter(o=>new Date(o.createdAt)>new Date(Date.now()-7*86400000)).length,'Самостоятельно · офис · через клиента')}</div><div class="grid-main"><div><section class="panel"><div class="panel-head"><div><h2>Требуют решения ${badge(state.signals.length,'orange')}</h2><p>Сгруппированы по ответственным · фокусные сразу</p></div></div>${signalList(state.signals.filter(x=>!filter.owner||x.ownerId===filter.owner).filter(x=>!x.objectId||filtered().some(o=>o.id===x.objectId)),6)}</section><section class="panel"><div class="panel-head"><div><h2>Движение по воронке</h2><p>Текущее распределение по подтверждённым условиям</p></div>${button('Команда →','team','','link-button')}</div>${funnel(filtered())}</section></div><div><section class="panel"><div class="panel-head"><h2>Фокусные объекты</h2>${badge(filtered().filter(o=>o.focus).length)}</div>${filtered().filter(o=>o.focus).map(focusCard).join('')||'<div class="empty">Нет фокусных объектов</div>'}</section><section class="panel"><div class="panel-head"><h2>Территория команды</h2>${button('Вся карта ↗','map','','link-button')}</div><div id="map" class="map small-map"></div><div class="map-note">Цифра — число наших продуктов · красная точка — сигнал</div></section></div></div>`;}
function signalList(items,limit=1000){const sorted=[...items].sort((a,b)=>a.ownerId.localeCompare(b.ownerId)||Number(b.focus)-Number(a.focus));return sorted.slice(0,limit).map(x=>{const o=state.objects.find(o=>o.id===x.objectId);return `<div class="signal-row"><div class="signal-icon ${x.focus?'critical':''}">!</div><div class="signal-text"><h3>${esc(x.title)}</h3><p>${esc(o?.name||uname(x.ownerId))} · ${esc(x.detail)}</p><div class="signal-meta">${esc(uname(x.ownerId))} · с ${dateTime(x.firstSeen)} ${x.focus?badge('Фокус','red'):''}</div>${(x.comments||[]).slice(-1).map(c=>`<div class="comment">${esc(c.text)}</div>`).join('')}</div><div class="actions">${o?button('Открыть','openObject',`data-id="${o.id}"`):''}${o&&editable(o)?button('Задача','plan',`data-id="${o.id}"`):''}${['leader','admin','owner','key'].includes(state.user.role)?button('Комментарий','comment',`data-id="${esc(x.id)}"`):''}</div></div>`;}).join('')+(items.length>limit?`<div class="panel-body muted small">Показаны первые ${limit} из ${items.length}. Все сигналы — в разборе команды.</div>`:'')||'<div class="empty">Нет сигналов для вашего внимания.<br>Обычные сигналы видны РОПу через заданный срок, фокусные — сразу.</div>';}
function products(o){return `<div class="products">${state.settings.products.map(p=>`<span class="product ${o.ourProducts?.includes(p.id)?'ours':''}">${esc(p.name)}</span>`).join('')}</div>`;}
function focusCard(o){const next=nextStep(o);return `<div class="focus-card" role="button" tabindex="0" data-object="${o.id}"><div class="flex between">${badge(construction(o.constructionStage),'blue')}${badge(stageNames[o.stage-1],o.stage>=8?'green':'orange')}</div><h3>${esc(o.name)}</h3>${products(o)}<div class="focus-meta"><span>${esc(uname(o.ownerId))}</span><span>${scaleNames[o.scale]}</span></div><p class="small ${next&&new Date(next.dueAt)<new Date()?'danger':'muted'}">${next?'→ '+esc(next.title)+' · '+fmt(next.dueAt):'Следующий шаг не назначен'}</p></div>`;}
function funnel(objs){const counts=stageNames.map((_,i)=>objs.filter(o=>o.stage===i+1).length),max=Math.max(1,...counts);return `<div class="funnel">${counts.map((n,i)=>`<div class="funnel-col"><div class="funnel-bar" style="height:${Math.max(20,n/max*115)}px">${n}</div><div class="funnel-label">${i+1}. ${stageNames[i]}</div></div>`).join('')}</div>`;}
function mapView(){return `${filters(true)}<div class="toolbar">${canCreate()?button(picking?'Нажмите на карту…':'+ Точка на карте','pick','','primary'):''}${button('Моё местоположение','locate')}<span class="small muted">${filtered().length} объектов · границы территории пунктиром</span></div><div class="map-layout"><section class="panel"><div id="map" class="map"></div><div class="legend">${[['#fafaf7','Выявлен'],['#d89553','В работе'],['#6c9a61','Наш клиент'],['#2a7864','Партнёрство'],['#d84834','Есть сигнал']].map(([c,n])=>`<span><i class="legend-dot" style="background:${c};border:1px solid #aaa"></i>${n}</span>`).join('')}</div><div class="map-note">Размер — масштаб · обводка — стадия стройки · ореол — фокус · цифра — наши продукты.<br>Карта требует сети; данные карточек и черновики сохраняются на устройстве.</div></section><section class="panel object-list">${filtered().map(o=>`<button data-act="openObject" data-id="${o.id}"><strong>${esc(o.name)}</strong><div class="flex wrap">${badge(construction(o.constructionStage),'blue')}${o.focus?badge('Фокус','orange'):''}</div><p class="small muted">${esc(uname(o.ownerId))}</p></button>`).join('')||'<div class="empty">Нет объектов по фильтрам</div>'}</section></div>`;}
function objectsView(){return `${filters(true)}<div class="flex between section-space"><p class="muted small">${filtered().length} объектов · этапы вычисляются автоматически</p><a href="./api/export?type=objects">Скачать Excel ↗</a></div><section class="panel section-space table-wrap"><table><thead><tr><th>Объект</th><th>Ответственный</th><th>Этап / стройка</th><th>Продукты</th><th>Следующий шаг</th></tr></thead><tbody>${filtered().map(o=>`<tr data-object="${o.id}" tabindex="0"><td><strong>${esc(o.name)}</strong><span class="muted">${o.focus?'★ Фокус · ':''}${esc(o.address)}</span></td><td>${esc(uname(o.ownerId))}<p class="muted">${sourceNames[o.source]}</p></td><td>${badge(stageNames[o.stage-1],o.stage>=8?'green':'orange')}<p class="muted">${construction(o.constructionStage)}</p></td><td>${products(o)}</td><td>${esc(nextStep(o)?.title||'Не назначен')}<p class="muted">${fmt(nextStep(o)?.dueAt)}</p></td></tr>`).join('')}</tbody></table></section>`;}
function clientsView(){return `<div class="toolbar">${canCreate()?button('+ Клиент','newClient','','primary'):''}<a href="./api/export?type=clients">Скачать Excel ↗</a><span class="muted small">Один клиент — все его объекты. Карточки подготовлены к сопоставлению с Bitrix24.</span></div><section class="panel table-wrap"><table><thead><tr><th>Клиент</th><th>Профиль</th><th>Объекты</th><th>Без наших продуктов</th><th>Отношения ведёт</th></tr></thead><tbody>${state.clients.filter(c=>!c.archived).map(c=>{const objs=state.objects.filter(o=>ownParts(o).some(p=>p.clientId===c.id));return `<tr data-client="${c.id}" tabindex="0"><td><strong>${esc(c.name)} ${c.key?'★':''}</strong><span class="muted">${c.inn?'ИНН '+esc(c.inn):'ИНН не задан'} · ${c.source==='demo'?'демо':'ожидает сопоставления CRM'}</span></td><td>${esc(c.profile)}</td><td>${objs.length}</td><td>${objs.filter(o=>!o.ourProducts?.length).length}</td><td>${esc(uname(c.ownerId))}</td></tr>`;}).join('')}</tbody></table></section>`;}
function dayView(){const steps=state.steps.filter(x=>x.status==='planned'&&(state.user.role!=='field'||x.assigneeId===state.user.id)).sort((a,b)=>a.dueAt.localeCompare(b.dueAt));return `<div class="toolbar">${button('Показать на карте','todayMap')}<a href="./api/export?type=steps">Скачать план Excel ↗</a></div><div class="grid-main"><section class="panel"><div class="panel-head"><h2>Сегодня и ближайшие шаги</h2>${badge(steps.length,'orange')}</div>${steps.map(x=>{const o=state.objects.find(o=>o.id===x.objectId);return `<div class="signal-row"><div class="signal-icon">→</div><div class="signal-text"><h3>${esc(x.title)}</h3><p>${esc(o?.name)} · ${esc(uname(x.assigneeId))}</p>${badge(dateTime(x.dueAt),new Date(x.dueAt)<new Date()?'red':'green')} ${x.reschedules?badge('Переносов: '+x.reschedules,'orange'):''}</div><div class="actions">${o&&editable(o)?button('Записать результат','action',`data-id="${x.objectId}" data-step="${x.id}"`)+button('Перенести','reschedule',`data-id="${x.objectId}" data-step="${x.id}"`):button('Открыть','openObject',`data-id="${x.objectId}"`)}</div></div>`;}).join('')||'<div class="empty">Нет запланированных шагов</div>'}</section><div><section class="panel"><div class="panel-head"><h2>Новые передачи</h2></div>${state.objects.filter(o=>o.handoffAt&&!o.acceptedAt&&(state.user.role!=='field'||o.ownerId===state.user.id)).map(o=>`<div class="focus-card"><h3>${esc(o.name)}</h3><p class="small muted">Передан ${dateTime(o.handoffAt)}</p>${editable(o)?button('Принять и назначить визит','accept',`data-id="${o.id}"`):''}</div>`).join('')||'<div class="empty">Все передачи приняты</div>'}</section><section class="panel"><div class="panel-head"><h2>Сигналы по моей работе</h2></div>${signalList(state.signals,6)}</section></div></div>`;}
function teamView(){const since=Date.now()-7*86400000;return `<div class="notice">За последние 7 дней. Недельные нормативы применяются к текущей календарной неделе; неутверждённые значения отмечены в настройках.</div><section class="panel section-space table-wrap"><table><thead><tr><th>Менеджер</th><th>Визиты</th><th>Новые сам</th><th>В работе</th><th>Продуктов / объект</th><th>2+ продукта</th><th>Просрочки</th></tr></thead><tbody>${state.users.filter(u=>u.role==='field').map(u=>{const os=state.objects.filter(o=>o.ownerId===u.id&&!o.restricted),steps=state.steps.filter(x=>x.assigneeId===u.id&&x.status==='planned');return `<tr><td><strong>${esc(u.name)}</strong></td><td>${state.actions.filter(a=>a.authorId===u.id&&a.type==='visit'&&new Date(a.at)>=since).length}</td><td>${os.filter(o=>o.source==='self'&&o.createdBy===u.id&&new Date(o.createdAt)>=since).length}</td><td>${os.filter(o=>o.state==='active').length}</td><td>${os.length?(os.reduce((n,o)=>n+o.ourProducts.length,0)/os.length).toFixed(1):'—'}</td><td>${os.length?Math.round(os.filter(o=>o.ourProducts.length>=2).length/os.length*100)+'%':'—'}</td><td>${steps.filter(x=>new Date(x.dueAt)<new Date()).length} / ${steps.length}</td></tr>`;}).join('')}</tbody></table></section><div class="grid-main"><section class="panel"><div class="panel-head"><h2>Движение за 7 дней</h2></div><div class="panel-body"><div class="detail-grid"><div><span>Переходы вперёд</span><b>${state.audit.filter(a=>a.event==='stage-progress'&&new Date(a.at)>=since).length}</b></div><div><span>Новые участники</span><b>${state.participations.filter(p=>new Date(p.createdAt)>=since).length}</b></div><div><span>Новые возможности</span><b>${state.opportunities.filter(p=>new Date(p.createdAt)>=since).length}</b></div><div><span>Потерянные объекты</span><b>${state.objects.filter(o=>o.state==='lost').length}</b></div></div><p class="small muted">История демонстрации начинается с запуска: прошлые переходы не выдумываются.</p></div>${funnel(state.objects)}</section><section class="panel"><div class="panel-head"><h2>Покрытие продуктами</h2></div><div class="panel-body">${state.settings.products.map(p=>`<div class="section-space"><div class="flex between"><strong>${esc(p.name)}</strong><span>${state.objects.filter(o=>o.ourProducts?.includes(p.id)).length} объектов</span></div><div class="progress"><div style="width:${state.objects.length?state.objects.filter(o=>o.ourProducts?.includes(p.id)).length/state.objects.length*100:0}%"></div></div><p class="small muted">У конкурента: ${state.opportunities.filter(x=>x.product===p.id&&x.status==='competitor').length} · не выяснено: ${state.opportunities.filter(x=>x.product===p.id&&x.status==='unknown').length} возможностей</p></div>`).join('')}</div></section></div><section class="panel"><div class="panel-head"><h2>Сигналы команды</h2><a href="./api/export?type=signals">Excel ↗</a></div>${signalList(state.signals)}</section>`;}
function settingsView(){return `<section class="panel"><div class="panel-head"><div><h2>Ритм работы</h2><p>Значения из ТЗ — настраиваемые черновики</p></div>${isLeader()?button('Изменить нормативы','norms'):''}</div><div class="panel-body settings-grid">${Object.entries(normLabels).map(([k,v])=>`<div><p class="small muted">${v}</p><p class="metric-big">${state.settings.thresholds[k]??'Не задан'}</p></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><h2>Территории</h2><p>Изменение границ не переписывает владельцев существующих объектов</p></div>${isLeader()?button('+ Территория','territory'):''}</div><div class="panel-body">${state.territories.map(t=>`<div class="flex between section-space"><div><i class="territory-swatch" style="background:${esc(t.color)}"></i>${esc(t.name)}<p class="small muted">${esc(uname(t.ownerId))}</p></div>${isLeader()?button('Изменить','territory',`data-id="${t.id}"`):''}</div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>Справочники и карта</h2>${isLeader()?button('Настроить','dictionaries'):''}</div><div class="panel-body"><p>Подложка: ${state.settings.map.provider==='yandex'?'Яндекс Карты':'OpenStreetMap · тестовый просмотр'}. Продукты и связь со стадиями редактируются без изменения кода.</p><p class="small muted">Яндекс Карты требуют ключ и подходящую лицензию. Telegram, SSO, Bitrix24 и 1С подключает разработчик по инструкции передачи. В этой версии уведомления отображаются внутри модуля.</p></div></section><section class="panel"><div class="panel-head"><h2>История и выгрузки</h2></div><div class="panel-body flex wrap">${['actions','steps','signals','opportunities','audit','territories'].map(t=>`<a href="./api/export?type=${t}">${({actions:'Действия',steps:'Шаги',signals:'Сигналы',opportunities:'Возможности',audit:'Аудит',territories:'Территории'})[t]} Excel ↗</a>`).join('')}</div></section>`;}
const normLabels={focusTouch:'Касание фокусного · дней',mediumTouch:'Касание среднего · дней',otherTouch:'Касание остальных · дней',firstVisitBusinessDays:'Первый визит · рабочих дней',quoteBusinessDays:'Ответ на КП · рабочих дней',handoffHours:'Передача офиса · часов',competitorDays:'Проверка конкурентов · дней',decisionMakerDays:'Контакт с ЛПР · дней',reschedules:'Порог переносов',managerDelayHours:'Эскалация РОПу · часов',duplicateMeters:'Проверка дубля · метров',visitRadiusMeters:'Радиус визита · метров',weeklyVisits:'Визитов в неделю',weeklyObjects:'Новых объектов в неделю',overdueShare:'Порог просрочек · %'};
function openObject(id){const o=state.objects.find(o=>o.id===id);if(!o)return;if(o.restricted){toast('Чужая территория: доступна точка для проверки дубля. Полная карточка — у владельца.');return;}selected=id;detailTab='overview';renderDrawer();}
function closeDrawer(){selected=null;$('.drawer')?.remove();$('.scrim')?.remove();}
function renderDrawer(){const o=state.objects.find(o=>o.id===selected);$('.drawer')?.remove();$('.scrim')?.remove();if(!o){selected=null;return;}const allowed=editable(o);document.body.insertAdjacentHTML('beforeend',`<div class="scrim" data-act="closeDrawer"></div><aside class="drawer" aria-label="Карточка объекта"><header class="drawer-head"><div class="flex between"><span class="eyebrow">ОБЪЕКТ · ${sourceNames[o.source]}</span>${button('✕','closeDrawer','aria-label="Закрыть карточку"','ghost')}</div><h2>${esc(o.name)}</h2><p class="small muted">${esc(o.address)}</p><div class="flex wrap section-space">${badge(stageNames[o.stage-1],o.stage>=8?'green':'orange')}${o.focus?badge('Фокусный','red'):''}${badge(({active:'В работе',paused:'На паузе',lost:'Потерян',closed:'Закрыт'})[o.state])}</div></header><div class="drawer-body"><div class="flex wrap">${allowed||state.user.role==='key'?button('+ Действие','action',`data-id="${o.id}"`,'primary'):''}${allowed?button('Следующий шаг','plan',`data-id="${o.id}"`):''}<a target="_blank" rel="noopener" href="https://yandex.ru/maps/?rtext=~${o.lat}%2C${o.lng}&rtt=auto">Маршрут ↗</a></div><div class="tabs">${[['overview','Обзор'],['participants','Участники'],['opportunities','Продукты'],['history','История']].map(([id,n])=>button(n,'detailTab',`data-id="${id}"`,detailTab===id?'active':'')).join('')}</div>${detailContent(o,allowed)}</div></aside>`);}
function detailContent(o,allowed){if(detailTab==='participants')return `${allowed?button('+ Участник','participation',`data-id="${o.id}"`):''}${ownParts(o).map(p=>{const c=state.clients.find(c=>c.id===p.clientId);return `<div class="panel section-space"><div class="panel-body"><h3>${esc(c?.name)}</h3><p class="small muted">${partNames[p.role]} · ${esc(p.work)}</p>${p.decisionMaker?badge('Выбирает подрядчиков','green'):''}<div>${button('Все объекты клиента →','openClient',`data-id="${p.clientId}"`,'link-button')}</div>${state.contacts.filter(x=>x.clientId===p.clientId).map(c=>`<p class="small">${esc(c.name)} · ${esc(c.position)} ${esc(c.phone)}</p>`).join('')}</div></div>`;}).join('')}`;
 if(detailTab==='opportunities')return `${allowed?button('+ Возможность','opportunity',`data-id="${o.id}"`):''}<p class="notice section-space">Одна возможность — продукт для конкретного участника. «У нас» требует ссылки на договор и отгрузку; введённые вручную основания не сверены с 1С.</p>${ownOpps(o).map(v=>`<div class="panel section-space"><div class="panel-body"><div class="flex between"><h3>${esc(pname(v.product))} · ${({rent:'аренда',sale:'продажа',buyback:'выкуп'})[v.dealType]}</h3>${badge(statusNames[v.status],v.status==='ours'?'green':'orange')}</div><p class="small muted">${esc(state.clients.find(c=>c.id===ownParts(o).find(p=>p.id===v.participationId)?.clientId)?.name)} · ${esc(v.volume||'Объём не задан')}</p><p class="small">Потребность: ${fmt(v.needDate)} ${v.returnDate?'· Вернуться '+fmt(v.returnDate):''}</p>${allowed?button('Изменить','opportunity',`data-id="${o.id}" data-op="${v.id}"`,'link-button'):''}</div></div>`).join('')}`;
 if(detailTab==='history')return `<div class="notice">История не редактируется. Исправление — новое действие «Уточнение».</div><div class="timeline">${state.actions.filter(a=>a.objectId===o.id).sort((a,b)=>b.at.localeCompare(a.at)).map(a=>`<div class="event"><strong>${actionNames[a.type]||a.type}</strong><p>${esc(a.result)}</p><span class="muted">${dateTime(a.at)} · ${esc(uname(a.authorId))}</span>${a.photo?`<img class="photo" src="${a.photo}" alt="Фото действия">`:''}</div>`).join('')||'<p class="muted">Действий пока нет</p>'}</div>`;
 const next=nextStep(o);return `<div class="detail-grid"><div><span>Владелец</span><b>${esc(uname(o.ownerId))}</b></div><div><span>Стадия стройки</span><b>${construction(o.constructionStage)}</b></div><div><span>Масштаб</span><b>${scaleNames[o.scale]}</b></div><div><span>Проверка конкурентов</span><b>${o.competitorCheckedAt?fmt(o.competitorCheckedAt):'Не проведена'}</b></div></div>${products(o)}<div class="panel section-space"><div class="panel-body"><span class="eyebrow">СЛЕДУЮЩИЙ ШАГ</span><h3>${esc(next?.title||'Не назначен')}</h3><p class="small muted">${dateTime(next?.dueAt)}</p></div></div>${allowed?`<div class="flex wrap">${button('Описание и потенциал','objectEdit',`data-id="${o.id}"`)}${o.source==='office'&&!o.handoffAt?button('Передать полевику','handoff',`data-id="${o.id}"`):''}${o.handoffAt&&!o.acceptedAt?button('Принять','accept',`data-id="${o.id}"`):''}${isLeader()?button('Сменить владельца','assign',`data-id="${o.id}"`):''}</div>`:''}<h3 class="section-space">Основания этапов</h3><div class="checklist">${stageNames.map((n,i)=>`<div class="${o.evidence[i]?'yes':'no'}">${o.evidence[i]?'✓':'○'} ${i+1}. ${n}</div>`).join('')}</div><p class="small muted">Этап — непрерывная цепочка выполненных условий. Наличие договора не скрывает пробелы в описании и контактах.</p>${o.photo?`<img class="photo" src="${o.photo}" alt="Фото объекта">`:''}${isLeader()?button('В архив','archive',`data-id="${o.id}"`,'ghost danger'):''}`;}
function field(label,name,type='text',value='',requiredFlag=false){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${requiredFlag?'required':''}></label>`;}
function select(label,name,items,value='',placeholder=null){return `<label>${label}<select name="${name}">${options(items,value,placeholder)}</select></label>`;}
const textarea=(label,name,value='')=>`<label>${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
const fields=()=>state.users.filter(u=>u.role==='field');
function nextFields(o={}){return `<fieldset style="border:1px solid #e4e6dd;border-radius:9px;padding:15px"><legend class="small">Обязательный следующий шаг</legend><div class="form-grid">${field('Что сделать','nextTitle','text','',true)}${field('Срок · Москва','nextDue','datetime-local',today()+'T17:00',true)}</div></fieldset>`;}
async function showForm(title,html,onSubmit,key='form'){
 const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2>${button('✕','closeDialog','aria-label="Закрыть форму"','ghost')}</div><form class="form"><div class="notice small">Черновик сохраняется на этом устройстве.</div>${html}<div class="error" hidden></div><div class="form-footer"><span class="muted small">Даты и время — Москва</span><button type="submit" class="primary">Сохранить</button></div></form>`;dialog.showModal();const form=dialog.querySelector('form');const draftKey='draft:'+state.user.id+':'+key;const saved=await get(draftKey);if(saved)for(const [k,v] of Object.entries(saved)){const input=form.elements.namedItem(k);if(input&&input.type!=='file'){if(input.type==='checkbox')input.checked=!!v;else input.value=v;}}
 const saveDraft=()=>{const d=Object.fromEntries(new FormData(form));for(const x of form.querySelectorAll('input[type=checkbox]'))d[x.name]=x.checked;for(const x of form.querySelectorAll('input[type=file]'))delete d[x.name];put(draftKey,d);};form.addEventListener('input',saveDraft);
 form.onsubmit=async e=>{e.preventDefault();const error=form.querySelector('.error'),submit=form.querySelector('[type=submit]');error.hidden=true;submit.disabled=true;try{const d=Object.fromEntries(new FormData(form));for(const x of form.querySelectorAll('input[type=checkbox]'))d[x.name]=x.checked;await onSubmit(d,form);await put(draftKey,null);dialog.close();}catch(e){error.textContent=e.message;error.hidden=false;}finally{submit.disabled=false;}};
 return form;
}
const nextData=d=>({title:d.nextTitle,dueAt:d.nextDue?new Date(d.nextDue+':00+03:00').toISOString():null});
function geolocate(){return new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude,accuracy:p.coords.accuracy}),()=>reject(new Error('Геолокация недоступна. Укажите координаты или причину вручную.')),{enableHighAccuracy:true,timeout:12000}):reject(new Error('Геолокация не поддерживается')));}
async function photo(input){if(!input||!input.size)return null;if(input.size>2000000)throw new Error('Фото больше 2 МБ. Выберите уменьшенное изображение.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(input);});}
async function newObject(coords={}){await showForm('Новый объект',`${field('Название объекта','name','text','',true)}${field('Адрес / ориентир','address','text','',true)}<div class="form-grid">${field('Широта','lat','number',coords.lat||'',true)}${field('Долгота','lng','number',coords.lng||'',true)}</div>${button('Определить местоположение','formGeo')}<div class="form-grid">${select('Тип','type',state.settings.objectTypes,'Жилой')}${select('Масштаб','scale',Object.entries(scaleNames).map(([id,name])=>({id,name})),'medium')}${select('Стадия стройки','constructionStage',state.settings.constructionStages,'preparation')}${select('Источник','source',Object.entries(sourceNames).map(([id,name])=>({id,name})),state.user.role==='office'?'office':'self')}</div><details><summary>Если пришли через клиента</summary>${select('Клиент','sourceClientId',state.clients,'','Выберите клиента')}${select('Роль клиента','clientRole',Object.entries(partNames).map(([id,name])=>({id,name})),'general')}</details><label>Фото · до 2 МБ<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" capture="environment"></label>${nextFields()}`,async(d,f)=>{await send('createObject',{...d,lat:Number(d.lat),lng:Number(d.lng),photo:await photo(d.photo),nextStep:nextData(d)});},'newObject');$('#dialog [name=lat]').step='any';$('#dialog [name=lng]').step='any';}
async function actionForm(o,completedStepId){const ps=ownParts(o);const vs=ownOpps(o);const canAction=editable(o)||state.user.role==='key';if(!canAction)return;const form=await showForm('Записать действие',`${select('Тип действия','type',Object.entries(actionNames).filter(([id])=>id!=='handoff').map(([id,name])=>({id,name})),'visit')}${select('Цель визита','purpose',['Первичный осмотр','Расширить контакты','Оценить потенциал','Проверить конкурентов','Поддержать отношения'])}<div class="form-grid">${select('Участник','participationId',ps.map(p=>({id:p.id,name:state.clients.find(c=>c.id===p.clientId)?.name})),'','Не выбран')}${select('Контакт','contactId',state.contacts.filter(c=>ps.some(p=>p.clientId===c.clientId)),'','Не выбран')}</div>${textarea('Результат одной фразой','result')}<div class="form-grid">${select('Подтвердите стадию стройки (при визите)','constructionStage',state.settings.constructionStages,o.constructionStage)}${select('Конкуренты проверены','competitors',[{id:'none',name:'Конкурентов нет'},{id:'present',name:'Конкуренты есть'}],'','Не проверяли')}</div><div class="flex">${button('Зафиксировать геолокацию','actionGeo')}<span id="geo-status" class="small muted">Ещё не зафиксирована</span></div>${field('Если геолокация недоступна — причина','geoReason')}<input type="hidden" name="geo"><label>Фото · до 2 МБ<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" capture="environment"></label><details><summary>КП и обратная связь</summary>${select('Возможность','opportunityId',vs.map(v=>({id:v.id,name:pname(v.product)+' · '+statusNames[v.status]})),'','Выберите возможность')}${select('Исходное КП (для ответа)','quoteId',state.actions.filter(a=>a.objectId===o.id&&a.type==='quote').map(a=>({id:a.id,name:dateTime(a.at)+' · '+pname(vs.find(v=>v.id===a.opportunityId)?.product)})),'','Выберите КП')}${select('Ответ','feedback',[{id:'accepted',name:'Принято'},{id:'refused',name:'Отказ'},{id:'later',name:'Позже'}])}${field('Вернуться к вопросу','returnDate','date')}</details>${nextFields(o)}<details><summary>Завершение объекта вместо следующего шага</summary>${select('Состояние','closeState',[{id:'lost',name:'Потерян'},{id:'closed',name:'Закрыт'}],'','Продолжаем работу')}${textarea('Причина отказа / закрытия','reason')}</details>`,async d=>{await send('action',{...d,objectId:o.id,completedStepId,geo:d.geo?JSON.parse(d.geo):null,photo:await photo(d.photo),nextStep:nextData(d)});},'action:'+o.id);
 form.elements.closeState.addEventListener('change',()=>{for(const name of ['nextTitle','nextDue'])form.elements[name].required=!form.elements.closeState.value;});
}
async function newClient(){await showForm('Новый клиент',`${field('Название / ФИО','name','text','',true)}<div class="form-grid">${field('ИНН','inn')}${select('Тип','type',[{id:'company',name:'Юрлицо'},{id:'ip',name:'ИП'},{id:'person',name:'Частное лицо'}])}</div>${select('Профиль','profile',state.settings.clientProfiles)}${field('Имя контакта','contactName')}<div class="form-grid">${field('Телефон','phone','tel')}${field('Должность','position')}</div><p class="notice">Перед сохранением проверяются ИНН, название и телефон. В рабочей интеграции поиск должен идти также в Bitrix24.</p>`,d=>send('createClient',d),'newClient');}
function openClient(id){const c=state.clients.find(x=>x.id===id);if(!c)return;const objs=state.objects.filter(o=>ownParts(o).some(p=>p.clientId===id));const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-head"><h2>${esc(c.name)}</h2>${button('✕','closeDialog','aria-label="Закрыть"','ghost')}</div><div class="panel-body"><p class="muted">${esc(c.profile)} · ${c.key?'Ключевой клиент':'Клиент'}</p><h3 class="section-space">Объекты клиента</h3>${objs.map(o=>`<div class="focus-card" data-act="clientObject" data-id="${o.id}"><h3>${esc(o.name)}</h3><p class="small muted">${partNames[ownParts(o).find(p=>p.clientId===id)?.role]} · ${esc(uname(o.ownerId))}</p>${products(o)}</div>`).join('')}<h3 class="section-space">Контакты</h3>${state.contacts.filter(x=>x.clientId===id).map(x=>`<p class="section-space">${esc(x.name)} · ${esc(x.position)}<br><span class="small muted">${esc(x.phone||'Телефон не указан')}</span></p>`).join('')}${['field','office','leader','admin','key'].includes(state.user.role)?button('+ Контакт','contact',`data-id="${id}"`):''}<p class="notice section-space">Вопрос для следующего касания: «Где ваши другие и следующие стройки?»</p></div>`;dialog.showModal();}
async function plan(o){await showForm('Следующий шаг · '+esc(o.name),`${nextFields(o)}`,d=>send('plan',{objectId:o.id,...{title:d.nextTitle,dueAt:nextData(d).dueAt}}),'plan:'+o.id);}
async function opportunity(o,id){const v=state.opportunities.find(x=>x.id===id)||{};await showForm(id?'Изменить возможность':'Новая возможность',`${select('Участник объекта','participationId',ownParts(o).map(p=>({id:p.id,name:state.clients.find(c=>c.id===p.clientId)?.name})),v.participationId)}<div class="form-grid">${select('Продукт','product',state.settings.products,v.product)}${select('Тип сделки','dealType',[{id:'rent',name:'Аренда'},{id:'sale',name:'Продажа'},{id:'buyback',name:'Выкуп'}],v.dealType)}</div>${select('Статус','status',Object.entries(statusNames).map(([id,name])=>({id,name})),v.status)}<div class="form-grid">${field('Ожидаемый объём','volume','text',v.volume)}${field('Срок потребности','needDate','date',v.needDate)}</div><details open><summary>Основания и альтернативные исходы</summary>${field('Договор (для «у нас»)','contractRef','text',v.contractRef)}${field('Отгрузка (для «у нас»)','shipmentRef','text',v.shipmentRef)}${field('Конкурент','competitor','text',v.competitor)}${field('Дата возврата к вопросу','returnDate','date',v.returnDate)}${textarea('Причина','reason',v.reason)}</details>`,d=>send('opportunity',{...d,id,objectId:o.id}),'opportunity:'+(id||o.id));}
async function review(){const users=fields(),u=users[reviewIndex%users.length];const os=state.objects.filter(o=>o.ownerId===u.id);const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-head"><h2>Разбор недели · ${reviewIndex+1} / ${users.length}</h2>${button('✕','closeDialog','aria-label="Закрыть"','ghost')}</div><div class="review-card"><h2>${esc(u.name)}</h2><p class="muted">${os.length} объектов · ${os.filter(o=>o.focus).length} фокусных</p><h3 class="section-space">Сигналы</h3>${signalList(state.signals.filter(x=>x.ownerId===u.id))}<h3 class="section-space">Фокусные объекты</h3>${os.filter(o=>o.focus).map(focusCard).join('')}<div class="flex between section-space">${button('← Предыдущий','reviewPrev')}${button('Следующий →','reviewNext','','primary')}</div></div>`;dialog.showModal();}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-act],[data-view],[data-object],[data-client]');if(!target)return;try{
 if(target.dataset.view){view=target.dataset.view;filter={};selected=null;render();return;}
 if(target.dataset.object){$('#dialog').close();openObject(target.dataset.object);return;}if(target.dataset.client){openClient(target.dataset.client);return;}
 const a=target.dataset.act,id=target.dataset.id,o=state?.objects.find(x=>x.id===id);
 if(a==='login')return await loginAs(id);if(a==='closeDialog')return $('#dialog').close();if(a==='closeDrawer')return closeDrawer();if(a==='refresh'){await refresh();return await sync();}if(a==='sync'){if(queue[0]?.error&&!confirm('Проверьте карточку перед повтором. Повторить сохранённое действие на текущих данных?'))return;return await sync(!!queue[0]?.error);}
 if(['map','team'].includes(a)){view=a;selected=null;render();return;}if(a==='resetFilters'){filter={};render();return;}if(a==='todayMap'){view='map';filter={today:true,owner:state.user.role==='field'?state.user.id:''};render();return;}
 if(a==='openObject')return openObject(id);if(a==='clientObject'){$('#dialog').close();return openObject(id);}if(a==='openClient')return openClient(id);if(a==='detailTab'){detailTab=id;renderDrawer();return;}if(a==='newObject')return newObject();if(a==='newClient')return newClient();if(a==='pick'){picking=true;render();toast('Нажмите на карту в нужном месте');return;}if(a==='locate'){const geo=await geolocate();return newObject(geo);}if(a==='formGeo'){const geo=await geolocate();$('#dialog [name=lat]').value=geo.lat;$('#dialog [name=lng]').value=geo.lng;return;}if(a==='actionGeo'){const geo=await geolocate();$('#dialog [name=geo]').value=JSON.stringify(geo);$('#geo-status').textContent='Координаты записаны · точность '+Math.round(geo.accuracy)+' м';return;}
 if(a==='action')return actionForm(o,target.dataset.step);if(a==='plan')return plan(o);if(a==='opportunity')return opportunity(o,target.dataset.op);
 if(a==='participation')return showForm('Добавить участника',`${select('Клиент','clientId',state.clients.filter(c=>!c.archived))}${select('Роль на объекте','role',Object.entries(partNames).map(([id,name])=>({id,name})))}${field('Вид работ','work','text','',true)}<label class="check"><input type="checkbox" name="decisionMaker"> Выбирает подрядчиков и поставщиков</label>`,d=>send('participation',{...d,objectId:id}),'part:'+id);
 if(a==='contact')return showForm('Новый контакт',`${field('Имя','name','text','',true)}${field('Должность','position')}${field('Телефон','phone','tel')}${field('Мессенджер','messenger')}`,d=>send('contact',{...d,clientId:id}),'contact:'+id);
 if(a==='reschedule')return showForm('Перенести шаг',`${field('Новый срок · Москва','due','datetime-local',today()+'T17:00',true)}${textarea('Причина переноса','reason')}`,d=>send('reschedule',{objectId:id,stepId:target.dataset.step,dueAt:new Date(d.due+':00+03:00').toISOString(),reason:d.reason}),'reschedule:'+target.dataset.step);
 if(a==='handoff'){await send('handoff',{objectId:id});return;}
 if(a==='accept')return showForm('Принять объект и назначить визит',nextFields(o),d=>send('accept',{objectId:id,nextStep:nextData(d)}),'accept:'+id);
 if(a==='comment')return showForm('Комментарий руководителя',textarea('Решение / комментарий','text'),d=>send('comment',{signalId:id,text:d.text}),'comment:'+id);
 if(a==='assign')return showForm('Передать объект',`${select('Новый владелец','ownerId',fields(),o.ownerId)}${textarea('Причина','reason')}`,d=>send('assign',{...d,objectId:id}),'assign:'+id);
 if(a==='archive')return showForm('Архивировать объект',`<p class="notice">История сохранится. Объект уйдёт из активных списков.</p>${textarea('Причина','reason')}`,d=>send('archive',{id,entity:'object',reason:d.reason}),'archive:'+id);
 if(a==='objectEdit')return showForm('Описание и потенциал',`${select('Стадия стройки','constructionStage',state.settings.constructionStages,o.constructionStage)}<div class="form-grid">${state.settings.products.map(p=>select('Потенциал: '+p.name,'potential_'+p.id,[{id:'none',name:'Нет'},{id:'small',name:'Небольшой'},{id:'medium',name:'Средний'},{id:'large',name:'Большой'}],o.potential?.[p.id],'Не оценён')).join('')}</div>${field('Ожидаемая следующая стадия','nextConstructionMonth','month',o.nextConstructionMonth)}${select('Состояние объекта','state',[{id:'active',name:'В работе'},{id:'paused',name:'Пауза до даты'},{id:'lost',name:'Потерян'},{id:'closed',name:'Закрыт'}],o.state)}${field('Возврат с паузы','pauseUntil','date',o.pauseUntil?.slice(0,10))}${textarea('Причина состояния','reason',o.reason)}${isLeader()?`<label class="check"><input type="checkbox" name="focus" ${o.focus?'checked':''}> Фокусный объект (крупные — всегда)</label>`:''}`,d=>send('updateObject',{objectId:id,constructionStage:d.constructionStage,potential:Object.fromEntries(state.settings.products.map(p=>[p.id,d['potential_'+p.id]])),state:d.state,pauseUntil:d.pauseUntil,reason:d.reason,nextConstructionMonth:d.nextConstructionMonth,...(isLeader()?{focus:d.focus}:{})}),'edit:'+id);
 if(a==='norms')return showForm('Нормативы',`<div class="form-grid">${Object.entries(normLabels).map(([k,n])=>field(n,k,'number',state.settings.thresholds[k]??'')).join('')}</div>${textarea('Нерабочие даты · YYYY-MM-DD, по одной в строке','holidays',state.settings.holidays.join('\n'))}<label class="check"><input type="checkbox" name="approved" ${state.settings.normsApproved?'checked':''}> Нормативы утверждены</label>`,d=>send('settings',{thresholds:Object.fromEntries(Object.keys(normLabels).map(k=>[k,d[k]===''?null:Number(d[k])])),holidays:d.holidays.split(/\s+/).filter(Boolean),normsApproved:d.approved}),'norms');
 if(a==='dictionaries')return showForm('Справочники и карта',`<h3>Продукты</h3>${state.settings.products.map(p=>field('Название продукта','product_'+p.id,'text',p.name,true)).join('')}${field('Добавить продукт (если нужен)','newProduct')}<h3>Что предлагать по стадиям</h3>${state.settings.constructionStages.map(c=>`<details><summary>${esc(c.name)}</summary>${state.settings.products.map(p=>`<label class="check"><input type="checkbox" name="rec_${c.id}_${p.id}" ${(state.settings.recommendations[c.id]||[]).includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</details>`).join('')}<h3>Критерии масштаба</h3>${Object.entries(scaleNames).map(([id,name])=>textarea(name,'scale_'+id,state.settings.scaleGuidance[id])).join('')}<h3>Карта</h3>${select('Сервис карты','provider',[{id:'osm',name:'OpenStreetMap · тестовая подложка'},{id:'yandex',name:'Яндекс Карты · нужен ключ'}],state.settings.map.provider)}<details><summary>Настройки подключения карты</summary>${field('Ключ Яндекс Карт','yandexKey','text',state.settings.map.yandexKey)}${field('Адрес сервиса тайлов HTTPS','tileUrl','text',state.settings.map.tileUrl)}${field('Подпись правообладателя карты','attribution','text',state.settings.map.attribution)}<p class="small muted">Ключ подключения карты должен быть ограничен доменом приложения.</p></details>`,d=>{const products=state.settings.products.map(p=>({...p,name:d['product_'+p.id]}));if(d.newProduct.trim())products.push({id:'product-'+Date.now(),name:d.newProduct.trim()});return send('settings',{products,recommendations:Object.fromEntries(state.settings.constructionStages.map(c=>[c.id,state.settings.products.filter(p=>d['rec_'+c.id+'_'+p.id]).map(p=>p.id)])),scaleGuidance:Object.fromEntries(Object.keys(scaleNames).map(id=>[id,d['scale_'+id]])),map:{provider:d.provider,yandexKey:d.yandexKey,tileUrl:d.tileUrl,attribution:d.attribution}});},'dictionaries');
 if(a==='territory'){const t=state.territories.find(t=>t.id===id)||{};return showForm('Территория',`${field('Название','name','text',t.name,true)}${select('Владелец','ownerId',fields(),t.ownerId)}${textarea('Точки границы по порядку: широта, долгота · каждая с новой строки','polygon',(t.polygon||[[38.9,45.1],[39,45.1],[39,45.2],[38.9,45.2]]).map(([lng,lat])=>lat+', '+lng).join('\n'))}${field('Цвет','color','color',t.color||'#227a66')}<p class="notice">Существующие объекты сохранят владельцев. Передача каждого объекта выполняется отдельно и записывается в историю.</p>`,d=>send('territory',{...d,id,polygon:d.polygon.trim().split('\n').map(line=>{const [lat,lng]=line.split(',').map(Number);return [lng,lat];})}),'territory:'+(id||'new'));}
 if(a==='review'){reviewIndex=0;return review();}if(a==='reviewPrev'||a==='reviewNext'){reviewIndex=(reviewIndex+(a==='reviewNext'?1:fields().length-1))%fields().length;return review();}
 }catch(error){toast(error.message);}});
document.addEventListener('change',async e=>{if(e.target.id==='user-select'){try{await loginAs(e.target.value);}catch(error){toast(error.message);}return;}if(e.target.dataset.filter){filter[e.target.dataset.filter]=e.target.type==='checkbox'?e.target.checked:e.target.value;render();}});
let searchTimer;document.addEventListener('input',e=>{if(e.target.dataset.filter==='search'){clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{filter.search=value;render();const input=$('[data-filter=search]');input?.focus();input?.setSelectionRange(value.length,value.length);},300);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-object],[data-client]')){e.preventDefault();e.target.click();}});
window.addEventListener('online',()=>{offline=false;sync().catch(e=>toast(e.message));});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
start().catch(e=>{$('#app').innerHTML=`<div class="login"><div class="login-card"><h1>Сервер недоступен</h1><p>${esc(e.message)}</p><p>Запустите start.cmd из папки модуля и обновите страницу.</p></div></div>`;});
